fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    // Pre-allocate a vector of capacity n for efficiency
    let mut result = Vec::with_capacity(n);

    // Build up the output vector one element at a time.
    // Loop invariant:
    //   0 <= i <= n,
    //   result.len() == i,
    //   all elements in result are 1.
    for _ in 0..n {
        result.push(1);
    }

    result
}

